<?php $this->layout('default'); use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$s = B::subscription($id); if ($s === null) { http_response_code(404); echo V::empty('Assinatura não encontrada.'); return; }
$manage = CmsAuth::can($admin, 'subscriptions.manage') && $s['status'] !== 'canceled'; $plans = []; foreach (B::plans() as $p) { if ($p['status'] === 'active' && $p['price_id']) { $plans[$p['id']] = $p['name']; } } ?>
<div class="cms-grid-2"><div><div class="cms-card"><h2><?= V::e($s['owner_name']) ?></h2><dl class="cms-dl"><dt>Contato</dt><dd><?= V::e($s['owner_email'] ?? '—') ?></dd><dt>Plano</dt><dd><?= V::e($s['plan_name']) ?></dd><dt>Ciclo</dt><dd><?= $s['billing_cycle'] === 'annual' ? 'Anual' : 'Mensal' ?></dd><dt>Valor contratado</dt><dd><?= V::money($s['contracted_amount']) ?></dd><dt>Início</dt><dd><?= V::date($s['started_at']) ?></dd><dt>Renovação</dt><dd><?= V::date($s['renews_at'], false) ?></dd><dt>Situação</dt><dd><?= V::badge($s['status'], V::SUB_STATUS[$s['status']] ?? $s['status']) ?></dd><?php if ($s['canceled_at']): ?><dt>Cancelada em</dt><dd><?= V::date($s['canceled_at']) ?> · <?= V::e($s['cancel_reason']) ?></dd><?php endif; ?></dl></div>
<?php if (CmsAuth::can($admin, 'charges.view')): ?><div class="cms-card"><h2>Cobranças</h2><?php $charges = B::subscriptionCharges($id); if ($charges === []): ?><?= V::empty('Sem cobranças.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Referência</th><th>Vencimento</th><th class="num">Valor</th><th>Situação</th></tr></thead><tbody><?php foreach ($charges as $c): ?><tr><td><a href="/cobrancas/<?= (int) $c['id'] ?>"><?= V::e($c['reference']) ?></a></td><td><?= V::date($c['due_date'], false) ?></td><td class="num"><?= V::money($c['amount']) ?></td><td><?= V::badge($c['status'], V::CHARGE_STATUS[$c['status']] ?? $c['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div><?php endif; ?>
<div class="cms-card"><h2>Histórico</h2><?php foreach (B::subscriptionEvents($id) as $e): ?><p><small><?= V::date($e['created_at']) ?> · <?= V::e($e['event_type']) ?><?= $e['to_status'] ? ' · ' . V::e(V::SUB_STATUS[$e['to_status']] ?? $e['to_status']) : '' ?><?= $e['contracted_amount'] !== null ? ' · ' . V::money($e['contracted_amount']) : '' ?><?= $e['note'] !== '' ? ' · ' . V::e($e['note']) : '' ?> · <?= V::e($e['actor_email'] ?? 'Sistema') ?></small></p><?php endforeach; ?></div></div>
<aside><?php if ($manage): ?><form class="cms-card" method="post" action="/acao/subscription-plan" data-confirm="Alterar o plano desta assinatura?"><h2>Alterar plano</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Novo plano', 'plan_id', $s['plan_id'], ['type' => 'select', 'choices' => $plans]) ?><?= V::field('Ciclo', 'billing_cycle', $s['billing_cycle'], ['type' => 'select', 'choices' => ['monthly' => 'Mensal', 'annual' => 'Anual']]) ?><?= V::field('Observação', 'note') ?><button class="cms-btn">Alterar</button></form>
<form class="cms-card" method="post" action="/acao/subscription-cancel" data-confirm="Cancelar esta assinatura?"><h2>Cancelar</h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><?= V::field('Motivo', 'reason', '', ['type' => 'textarea', 'rows' => 2, 'required' => true]) ?><button class="cms-btn-danger">Cancelar assinatura</button></form><?php endif; ?>
<?php if (CmsAuth::can($admin, 'charges.manage') && in_array($s['status'], ['active', 'past_due'], true) && $s['renews_at']): ?><div class="cms-card"><h2>Renovação</h2><?= V::actionButton('subscription-renewal', 'Emitir cobrança de renovação', ['id' => $id]) ?></div><?php endif; ?></aside></div>
